// Stores uploaded files in an upload directory.
const fs = require('fs');
const path = require('path');

function save(dir, filename, data) {
  const file = path.join(dir, filename);
  fs.writeFileSync(file, data);
  return file;
}

module.exports = { save };

const fs = require('fs');
const os = require('os');
const path = require('path');
const uploads = require('../lib/uploads');

test('saves a file', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'uploads-'));
  uploads.save(dir, 'a.txt', 'x');
  expect(fs.existsSync(path.join(dir, 'a.txt'))).toBe(true);
});
